def error_rate(window_minutes=5, now_ts=None, min_sustained_duration_sec=120):
    """Return fraction of failures over the last `window_minutes`.

    Failures lasting less than `min_sustained_duration_sec` are ignored, to
    reduce alert noise from short blips.
    """
    if now_ts is None:
        now_ts = EVENTS[-1][0] if EVENTS else 0
    cutoff = now_ts - window_minutes * 60

    bucket_success = []
    failure_timestamps = []
    for t, s in EVENTS:
        if t >= cutoff:
            bucket_success.append(s)
            if not s:
                failure_timestamps.append(t)

    if not failure_timestamps:
        return 0.0

    failure_duration = max(failure_timestamps) - min(failure_timestamps)

    if failure_duration < min_sustained_duration_sec:
        return 0.0

    if not bucket_success:
        return 0.0

    return 1 - (sum(1 for s in bucket_success if s) / len(bucket_success))
